def restart
      @status = :restart
      @runner.restart
    end

def allowed?(domain)
      !rule_for(domain).nil?
    end

def wiki_path?(path)
      NamespacePathValidator.valid_path?(path) && path.end_with?('.wiki')
    end

def initialize(user, start_date: '1970-01-01', end_date: nil)
    @user = user
    @start_date = start_date
    @end_date = end_date
  end

def initialize(driver)
        super(driver)
        @aliases = {}
      end

def respond_to?(method, include_private = false)
        if BODY_METHODS.key?(method)
          @buf.respond_to?(method)
        else
          super
        end
      end

def run
      pid = Process.spawn(
        @env,
        *@cmd,
        **@options
      )
      @wait_thread = Process.detach(pid)
      @wait_thread
    end

def matches(name)
        page.evaluate_script("Discourse.lookup('service:capabilities').viewport[#{name.to_json}]")
      end

def from_raw_tool(raw_message)
          if @responses_api
            {
              type: "function_call_output",
              call_id: raw_message[:id],
              output: raw_message[:content],
            }
          else
            {
              role: "tool",
              tool_call_id: raw_message[:id],
              content: raw_message[:content],
              name: raw_message[:name],
            }
          end
        end
